function startLab(config){if(battle&&!battle.custom){toast('Завершите бой кампании перед испытанием');return;}labConfig=config;battle=customBattle(config);controlSide=config.sides[0].ai?1:0;selected=[];squads={};battlePanel=true;bcam=new Camera(BW,BH);speed=0;dirty=true;closeMenu();}
