function saveDiplomacyLab(quiet=false){if(!diplomacyLab||state?.sandboxKind!=='diplomacy')return false;try{localStorage.setItem(dipKey,JSON.stringify({state:serialize(state),battle:battle?.custom?null:battle,config:diplomacyLab.config,samples:diplomacyLab.samples.slice(-720),runs:diplomacyLab.runs||[]}));if(!quiet)toast('Политический опыт сохранён');return true;}catch(e){toast('Не удалось сохранить опыт: '+e.message);return false;}}
function loadDiplomacyLab(){try{const raw=localStorage.getItem(dipKey);if(!raw)throw Error('Нет сохранённого опыта');const data=JSON.parse(raw),next=restore(data.state);if(next.sandboxKind!=='diplomacy'||!next.politics)throw Error('Несовместимое сохранение');if(!state?.sandbox)heldCampaign=state;state=next;campaignLab=null;economicLab=null;diplomacyLab={config:data.config,samples:data.samples?.length?data.samples:[diplomaticSample(state)],runs:data.runs||[]};resetView();tab='diplomacy';dipView='council';mode='diplomatic';if(data.battle&&state.battle){battle=data.battle;bcam=new Camera(BW,BH);battlePanel=true;controlSide=battle.armies.findIndex(a=>a.f===player());}closeMenu();changed('Опыт восстановлен');}catch(e){toast(e.message);}}
