function loadCampaignLab(){try{const raw=localStorage.getItem(labKey);if(!raw)throw Error('Нет сохранённого театра');const data=JSON.parse(raw),next=restore(data.state);if(next.sandboxKind!=='campaign')throw Error('Несовместимое сохранение');if(!state?.sandbox)heldCampaign=state;state=next;economicLab=null;diplomacyLab=null;campaignLab={config:data.config,samples:data.samples?.length?data.samples:[warSnapshot(state)]};campaignRuns=data.runs||[];resetView();tab='war';if(data.battle&&state.battle){battle=data.battle;bcam=new Camera(BW,BH);battlePanel=true;controlSide=battle.armies.findIndex(a=>a.f===player());}closeMenu();changed('Театр войны восстановлен');}catch(e){toast(e.message);}}
let campaignStored=false,storageQueue=Promise.resolve(),campaignDB=null,pendingGrand=null,loadingCampaign=false,preserveBackup=false;
function openCampaignDB(){if(!campaignDB)campaignDB=new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('IndexedDB недоступна'));return}const req=indexedDB.open('crown-and-marches-campaigns',1);req.onupgradeneeded=()=>req.result.createObjectStore('campaigns');req.onsuccess=()=>{req.result.onversionchange=()=>{req.result.close();campaignDB=null;};resolve(req.result)};req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('Хранилище заблокировано другой вкладкой'));}).catch(e=>{campaignDB=null;throw e});return campaignDB;}
async function campaignRecords(){const db=await openCampaignDB();return new Promise((resolve,reject)=>{const tx=db.transaction('campaigns','readonly'),st=tx.objectStore('campaigns'),primary=st.get('primary'),backup=st.get('backup');tx.oncomplete=()=>resolve([primary.result,backup.result].filter(Boolean));tx.onabort=tx.onerror=()=>reject(tx.error||Error('Чтение прервано'));});}
async function writeCampaign(raw){const db=await openCampaignDB();return new Promise((resolve,reject)=>{const tx=db.transaction('campaigns','readwrite'),st=tx.objectStore('campaigns'),old=st.get('primary');old.onsuccess=()=>{if(old.result?.raw===raw)return;if(old.result&&!preserveBackup)st.put(old.result,'backup');st.put({raw,savedAt:Date.now()},'primary');};tx.oncomplete=()=>{preserveBackup=false;resolve();};tx.onabort=tx.onerror=()=>reject(tx.error||Error('Запись прервана'));});}
function checkCampaignStorage(){return campaignRecords().then(rows=>{campaignStored=rows.length>0;const btn=modalbody.querySelector('[data-act="load"]');if(campaignStored&&btn)btn.disabled=false;}).catch(()=>{});}
function campaignPayload(){return JSON.stringify({format:2,campaign:serialize(state),battle,quality});}
function safeSave(quiet=false){if(state?.sandboxKind==='atlas')return saveAtlasCampaign(quiet);if(state?.sandboxKind==='society')return saveSociety(quiet);if(state?.sandboxKind==='discovery')return saveDiscovery(quiet);if(state?.sandboxKind==='diplomacy')return saveDiplomacyLab(quiet);if(state?.sandboxKind==='campaign')return saveCampaignLab(quiet);if(!state||state.sandbox||battle?.custom)return false;try{const raw=campaignPayload();storageQueue=storageQueue.catch(()=>{}).then(async()=>{try{await writeCampaign(raw);campaignStored=true;if(!quiet)toast('Кампания сохранена');}catch(err){try{localStorage.setItem(key,JSON.stringify({format:2,raw,savedAt:Date.now()}));campaignStored=true;if(!quiet)toast('Кампания сохранена в резервном хранилище');}catch(e){toast('Не удалось сохранить: хранилище недоступно или переполнено. Экспортируйте кампанию.');}}});return true}catch(e){toast('Не удалось подготовить сохранение: '+e.message);return false}}
function applyCampaign(raw){const data=JSON.parse(raw);const next=restore(data.campaign||raw);if(next.sandbox)throw Error('Это сохранение лаборатории, а не кампании');enablePolitics(next);enableDiscovery(next);enableSociety(next);next.grand??={schema:1,goal:'sandbox',started:next.day};if(!next.grand.experience)grandReview(next,true);state=next;quality=data.quality==='low'?'low':'high';resetView();if(data.battle&&state.battle){battle=data.battle;bcam=new Camera(BW,BH);battlePanel=true;}closeMenu();return true;}
async function load(){if(loadingCampaign)return;loadingCampaign=true;const previous=state;try{await storageQueue;let records=[];try{records=await campaignRecords()}catch{}try{const raw=localStorage.getItem(key);if(raw){const v=JSON.parse(raw);records.push(v.raw?{raw:v.raw,savedAt:v.savedAt||0}:{raw,savedAt:0});}}catch{}records.sort((a,b)=>b.savedAt-a.savedAt);if(!records.length)throw Error('Нет сохранения');let error;for(let i=0;i<records.length;i++){try{applyCampaign(records[i].raw);if(i>0){preserveBackup=true;toast('Восстановлена резервная копия');safeSave(true);}return true}catch(e){error=e;state=previous;activateWorld(previous);}}throw error||Error('Сохранения повреждены');}catch(e){toast(e.message);return false}finally{loadingCampaign=false;}}
function exportGrandCampaign(){if(!state||state.sandbox||battle?.custom){toast('Нет активной кампании');return}const url=URL.createObjectURL(new Blob([campaignPayload()],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='crown-and-marches-'+state.seed.replace(/[^a-z0-9_-]/gi,'_')+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importCampaign(file){if(!file)return;if(state&&!confirm('Заменить открытую кампанию импортированной?'))return;const previous=state;try{applyCampaign(await file.text());safeSave();}catch(e){state=previous;activateWorld(previous);toast('Импорт отклонён: '+e.message);}}
function grandConfig(){const size=$('worldsize')?.value||'standard',spec=WORLD_SIZES[size],n=clamp(Math.floor(+$('worldstates')?.value||spec.states),2,spec.states);return {seed:$('seed')?.value||'1080',worldSize:size,states:n,mapShape:$('worldshape')?.value||'classic',playerFaction:clamp(+$('worldplayer')?.value||0,0,n-1),goal:$('worldgoal')?.value||'sandbox'};}
function updateWorldOptions(){const size=$('worldsize'),n=$('worldstates'),f=$('worldplayer');if(!size||!n||!f)return;const max=WORLD_SIZES[size.value].states;n.max=max;n.value=clamp(Math.floor(+n.value||max),2,max);const selected=+f.value;f.innerHTML=Array.from({length:+n.value},(_,i)=>'<option value="'+i+'"'+(selected===i?' selected':'')+'>'+escape(FACTIONS[i]||'Держава '+(i+1))+'</option>').join('');}
function previewGrand(){const previous=state;try{const cfg=grandConfig(),preview=grandCampaign(cfg);const list=preview.states.map(st=>{const c=preview.cities.find(q=>q.f===st.id),g=preview.society.architecture.governments[st.id];return '<div class="entry row"><span>'+escape(st.name)+'<br><small>'+escape(g.institutions.name)+' · '+num(c.pop)+' жителей · '+num(st.gold)+' монет</small></span>'+button('grandchoose','Выбрать',st.id)+'</div>'}).join('');pendingGrand=cfg;modalbody.innerHTML='<h1>Державы нового мира</h1><p>'+escape(cfg.seed)+' · '+preview.owner.length.toLocaleString('ru-RU')+' клеток</p><canvas id="grandpreviewmap" aria-label="Карта стартовых держав" style="width:100%;height:auto;image-rendering:pixelated;border:1px solid #ad7b3f"></canvas>'+list+'<div class="actions">'+button('menu','Назад')+'</div>';const canvas=$('grandpreviewmap');canvas.width=W;canvas.height=H;const ctx=canvas.getContext('2d'),pixels=ctx.createImageData(W,H);for(let i=0;i<N;i++){const f=preview.owner[i],hex=f>=0?PALETTE[f]:preview.map.land[i]?'#a69b76':'#334e58',p=i*4;pixels.data[p]=parseInt(hex.slice(1,3),16);pixels.data[p+1]=parseInt(hex.slice(3,5),16);pixels.data[p+2]=parseInt(hex.slice(5,7),16);pixels.data[p+3]=255;}ctx.putImageData(pixels,0,0);for(const city of preview.cities){ctx.fillStyle='#fff2c4';ctx.fillRect(xx(city.i)-1,yy(city.i)-1,3,3);}}catch(e){toast(e.message)}finally{activateWorld(previous);}}
function resetView(){atlas.atlasSurface?.reset();activateWorld(state);cityPage='overview';alertSeen=new Set();layerMore=false;historyType='all';historyRealm='all';historyRegion='all';historyPeriod='all';navalLab=null;battle=null;selection=null;tab=null;placing=null;operationIds=[];warGoals=[];speed=0;cam=new Camera(W,H);atlas.cache='';dirty=true;home();renderUI()}
