function saveDiscovery(quiet=false){if(!discoveryLab||state?.sandboxKind!=='discovery')return false;try{localStorage.setItem(discKey,JSON.stringify({state:serialize(state),config:discoveryLab.config,samples:discoveryLab.samples,runs:discoveryRuns}));if(!quiet)toast('Атлас сохранён');return true}catch(e){toast('Не удалось сохранить атлас: '+e.message);return false}}
