 if(cityPage==='military')return h+'<div class="rows">'+stat('Крепость',c.fort)+stat('Склад пищи',c.depot[9].toFixed(1))+stat('Потери',c.originLoss||0)+stat('Возвращаются',num(c.returning||0))+'</div>'+(allowed?'<div class="actions">'+button('build','Стены · 55','fort')+UNIT.map((u,i)=>button('recruit',u[0],i)).join('')+button('depotbuy','Пища на склад +10',9)+button('depotbuy','Древесина +10',1)+button('depotbuy','Металл +5',11)+'</div>':'');
 if(cityPage==='land')return h+'<div class="rows">'+stat('Дороги',c.infra)+stat('Освоено',c.developed||0)+stat('Изолировано',c.isolated||0)+'</div>'+(allowed?'<div class="actions">'+button('found','Основать рядом')+button('build','Дороги · 30','road')+button('connect','Проложить дорогу')+button('districtassign','Присоединить клетку')+button('districtsplit','Разделить округ')+'</div>':'')+'<div class="section">Ресурсный потенциал</div><div class="rows">'+LABELS.slice(0,9).map((l,i)=>stat(l,num(c.potential[i]))).join('')+'</div>';
